const o=a=>{if(!a)return"";let n=a.replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");const c=[{class:"comment",regex:/(\/\/.*|#.*)/g},{class:"string",regex:/("[^"]*"|'[^']*')/g},{class:"keyword",regex:/\b(int|float|double|char|long|short|void|bool|if|else|while|for|do|return|break|continue|switch|case|default|struct|union|enum|typedef|sizeof|goto|static|extern|const|volatile|true|false|NULL|def|class|import|from|input|print|printf|scanf|main|include|#include|self|None|lambda|with|as|try|except|finally|raise|yield|async|await|var|let|const|function|=>|new|delete|type|public|private|protected)\b/g},{class:"number",regex:/\b(\d+\.?\d*|0x[0-9a-fA-F]+|0b[01]+)\b/g},{class:"function",regex:/\b([a-zA-Z_]\w*)(?=\s*\()/g},{class:"operator",regex:/(&amp;&amp;|\|\||&lt;=|&gt;=|==|!=|\+=|-=|\*=|\/=|%=|=&gt;|[&lt;&gt;=+\-*/%&|^!~?:]+)/g}],r=[];let e=n;return c.forEach((t,i)=>{e=e.replace(t.regex,s=>{if(s.startsWith("__HL_"))return s;const l=`__HL_${i}_${r.length}__`;return r.push({id:l,html:`<span class="${t.class}">${s}</span>`}),l})}),r.reverse().forEach(t=>{e=e.split(t.id).join(t.html)}),e};export{o as h};
